<?php $title='Edit gallery'; $active='galleries'; require_once __DIR__ . '/_layout.php'; $pdo=db(); $id=(int)($_GET['id']??0); $g=['title'=>'','slug'=>'','description'=>'','status'=>'draft']; if($id){$st=$pdo->prepare('SELECT * FROM galleries WHERE id=?');$st->execute([$id]);$g=$st->fetch() ?: $g;} if($_SERVER['REQUEST_METHOD']==='POST'){ $slug=$_POST['slug'] ?: slugify($_POST['title']); if($id){$st=$pdo->prepare('UPDATE galleries SET title=?,slug=?,description=?,status=? WHERE id=?');$st->execute([$_POST['title'],$slug,$_POST['description'],$_POST['status'],$id]);} else {$st=$pdo->prepare('INSERT INTO galleries(title,slug,description,status) VALUES(?,?,?,?)');$st->execute([$_POST['title'],$slug,$_POST['description'],$_POST['status']]);$id=(int)$pdo->lastInsertId();} if(!empty($_FILES['images']['name'][0])){ foreach($_FILES['images']['name'] as $k=>$name){ $file=['name'=>$_FILES['images']['name'][$k],'type'=>$_FILES['images']['type'][$k],'tmp_name'=>$_FILES['images']['tmp_name'][$k],'error'=>$_FILES['images']['error'][$k],'size'=>$_FILES['images']['size'][$k]]; $path=upload_image($file,'gallery'); if($path){$pdo->prepare('INSERT INTO gallery_images(gallery_id,file_path,caption,alt_text,sort_order) VALUES(?,?,?,?,?)')->execute([$id,$path,'','',0]);}}} redirect('gallery_edit.php?id='.$id); } $images=[]; if($id){$st=$pdo->prepare('SELECT * FROM gallery_images WHERE gallery_id=? ORDER BY sort_order,id');$st->execute([$id]);$images=$st->fetchAll();} ?>
<h1><?= $id?'Edit':'Create' ?> gallery</h1><form method="post" enctype="multipart/form-data" class="panel"><div class="form-row"><label>Title</label><input name="title" required value="<?=h($g['title'])?>"></div><div class="form-row"><label>Slug</label><input name="slug" value="<?=h($g['slug'])?>"></div><div class="form-row"><label>Description</label><textarea name="description"><?=h($g['description'])?></textarea></div><div class="form-row"><label>Status</label><select name="status"><option <?=$g['status']==='draft'?'selected':''?>>draft</option><option <?=$g['status']==='published'?'selected':''?>>published</option></select></div><div class="form-row"><label>Upload images</label><input type="file" name="images[]" accept="image/*" multiple></div><button class="btn">Save gallery</button></form><?php if($images): ?><section class="panel"><h2>Images</h2><div class="gallery-grid"><?php foreach($images as $im): ?><div><div class="thumb"><img src="../<?=h($im['file_path'])?>"></div><p><?=h($im['caption'])?></p></div><?php endforeach; ?></div></section><?php endif; ?><?php require __DIR__ . '/_footer.php'; ?>
